<template>
  <div class="designer-window">
    <header class="designer-header">
      <div class="brand"><strong>ContraBooks</strong><span>Visual Template Designer</span></div>
      <div class="template-title"><span>Template</span><input v-model="templateName" @change="saveName" /><span class="dirty" v-if="doc?.dirty">Unsaved changes</span></div>
      <div class="header-actions"><button @click="undo" :disabled="!canUndo">Undo</button><button @click="redo" :disabled="!canRedo">Redo</button><button @click="previewPrint">Print Preview</button><button class="primary" @click="save">Save Template</button></div>
    </header>
    <div class="workspace" v-if="doc">
      <aside class="left-rail">
        <div class="rail-title">Template</div>
        <button v-for="preset in presets" :key="preset" :class="{active: preset===activePreset}" @click="applyPreset(preset)"><span class="swatch" :class="preset.toLowerCase()"></span>{{ preset }}</button>
        <div class="rail-divider"></div>
        <div class="rail-title">Build</div>
        <button v-for="block in blocks" :key="block.id" @click="insertBlock(block)"><span class="plus">+</span>{{ block.label }}</button>
        <div class="rail-divider"></div>
        <div class="rail-title">Document</div>
        <button @click="showAdvanced=!showAdvanced">{{ showAdvanced ? 'Hide' : 'Show' }} Advanced HTML</button>
        <button @click="previewPrint">Print Preview</button>
      </aside>

      <main class="canvas-area">
        <div class="canvas-toolbar"><div><strong>{{ doc.type === 'SalesInvoice' ? 'Invoice' : doc.type }}</strong><span>Live data preview</span></div><div class="canvas-controls"><button @click="zoom-=.1">−</button><span>{{ Math.round(zoom*100) }}%</span><button @click="zoom+=.1">+</button><button @click="fit">Fit</button></div></div>
        <div class="paper-stage" @dragover.prevent @drop="dropElement">
          <div class="paper-shell" :style="{transform:`scale(${zoom})`}">
            <PrintContainer v-if="displayDoc && values" ref="printContainer" :print-schema-name="displayDoc.schemaName" :template="doc.template!" :values="values" :scale="1" :height="doc.height" :width="doc.width" @select-element="selectElement" />
          </div>
        </div>
      </main>

      <aside class="inspector-panel">
        <div class="inspector-header"><div><span>Inspector</span><strong>{{ selectedLabel || 'Template' }}</strong></div><button v-if="selectedId" @click="deleteElement">Delete</button></div>
        <div class="tabs"><button v-for="tab in tabs" :key="tab.id" :class="{active:tab.id===activeTab}" @click="activeTab=tab.id">{{ tab.label }}</button></div>
        <div class="inspector-body">
          <section v-if="activeTab==='layout'">
            <h3>Layout</h3><Row label="Alignment"><select v-model="controls.align" @change="style('text-align',controls.align)"><option>left</option><option>center</option><option>right</option><option>justify</option></select></Row>
            <Row label="Padding"><input v-model="controls.padding" @change="style('padding',controls.padding)" placeholder="8px" /></Row>
            <Row label="Margin top"><input v-model="controls.marginTop" @change="style('margin-top',controls.marginTop)" /></Row><Row label="Margin bottom"><input v-model="controls.marginBottom" @change="style('margin-bottom',controls.marginBottom)" /></Row>
            <Row label="Width"><input v-model="controls.width" @change="style('width',controls.width)" /></Row><Row label="Height"><input v-model="controls.height" @change="style('height',controls.height)" /></Row>
          </section>
          <section v-else-if="activeTab==='header'">
            <h3>Header</h3><Check label="Show company name" v-model="settings.companyName" @change="refreshTemplate"/><Check label="Show address" v-model="settings.address" @change="refreshTemplate"/><Check label="Show phone" v-model="settings.phone" @change="refreshTemplate"/><Check label="Show email" v-model="settings.email" @change="refreshTemplate"/><Check label="Show document title" v-model="settings.title" @change="refreshTemplate"/><Check label="Show document number" v-model="settings.number" @change="refreshTemplate"/>
            <button class="wide" @click="insertField('print.companyName')">Insert Company Name</button><button class="wide" @click="insertField('doc.name')">Insert Document Number</button>
          </section>
          <section v-else-if="activeTab==='fields'">
            <h3>Fields</h3><p class="hint">Add live accounting fields without editing HTML.</p><div class="field-list"><button v-for="field in fieldOptions" :key="field.path" @click="insertField(field.path)"><strong>{{ field.label }}</strong><small>{{ field.path }}</small></button></div>
          </section>
          <section v-else-if="activeTab==='columns'">
            <h3>Columns</h3><div class="column-row" v-for="(col,i) in columns" :key="col.key"><span>{{ col.label }}</span><input type="checkbox" v-model="col.visible" @change="updateColumn(i)"/><button @click="moveColumn(i,-1)">←</button><button @click="moveColumn(i,1)">→</button></div><button class="wide" @click="insertBlock({id:'table',label:'Items Table'})">Insert Items Table</button>
          </section>
          <section v-else-if="activeTab==='totals'"><h3>Totals</h3><Check label="Subtotal" v-model="settings.subtotal" @change="refreshTemplate"/><Check label="Discount" v-model="settings.discount" @change="refreshTemplate"/><Check label="Tax" v-model="settings.tax" @change="refreshTemplate"/><Check label="Payments / Credits" v-model="settings.payments" @change="refreshTemplate"/><Check label="Balance Due" v-model="settings.balance" @change="refreshTemplate"/></section>
          <section v-else-if="activeTab==='footer'"><h3>Footer</h3><Row label="Footer text"><textarea v-model="settings.footer" @change="refreshTemplate"></textarea></Row><Check label="Terms & Conditions" v-model="settings.terms" @change="refreshTemplate"/><Check label="Page numbers" v-model="settings.pageNumbers" @change="refreshTemplate"/></section>
          <section v-else-if="activeTab==='logo'"><h3>Logo</h3><div class="logo-card"><div class="logo-preview" v-if="logo"><img :src="logo" /></div><div class="logo-preview empty" v-else>CB</div><div><strong>Company Logo</strong><small>Uses Print Settings logo</small></div></div><button class="wide" @click="insertBlock({id:'logo',label:'Company Logo'})">Insert / Move Logo</button><Row label="Max width"><input v-model="controls.logoWidth" @change="style('max-width',controls.logoWidth)" /></Row><Row label="Max height"><input v-model="controls.logoHeight" @change="style('max-height',controls.logoHeight)" /></Row></section>
          <section v-else-if="activeTab==='typography'"><h3>Typography</h3><Row label="Font"><select v-model="settings.font" @change="setGlobalStyle('font-family',settings.font)"><option>Inter</option><option>Arial</option><option>Georgia</option><option>Times New Roman</option></select></Row><Row label="Size"><select v-model="controls.fontSize" @change="style('font-size',controls.fontSize)"><option v-for="s in fontSizes" :key="s">{{s}}</option></select></Row><Row label="Weight"><select v-model="controls.weight" @change="style('font-weight',controls.weight)"><option>400</option><option>500</option><option>600</option><option>700</option><option>800</option></select></Row><Row label="Style"><select v-model="controls.fontStyle" @change="style('font-style',controls.fontStyle)"><option>normal</option><option>italic</option></select></Row></section>
          <section v-else-if="activeTab==='colors'"><h3>Colors</h3><Row label="Text"><input type="color" v-model="controls.textColor" @change="style('color',controls.textColor)" /></Row><Row label="Fill"><input type="color" v-model="controls.fill" @change="style('background-color',controls.fill)" /></Row><Row label="Border"><input type="color" v-model="controls.border" @change="style('border-color',controls.border)" /></Row><Row label="Accent"><input type="color" v-model="settings.accent" @change="setGlobalStyle('border-color',settings.accent)" /></Row></section>
          <section v-else-if="activeTab==='print'"><h3>Print</h3><Row label="Paper"><select v-model="print.paper"><option>Letter</option><option>A4</option><option>Legal</option></select></Row><Row label="Orientation"><select v-model="print.orientation"><option>Portrait</option><option>Landscape</option></select></Row><Row label="Margins"><input v-model="print.margins" /></Row><Check label="Repeat table header" v-model="print.repeatHeader"/><Check label="Fit to one page width" v-model="print.fitWidth"/><button class="wide" @click="previewPrint">Open Print Preview</button></section>
          <section v-else><h3>Position</h3><div class="arrange"><button @click="move(-1)">↑ Move Up</button><button @click="move(1)">↓ Move Down</button><button @click="duplicate">Duplicate</button><button @click="nudge(-8)">←</button><button @click="nudge(8)">→</button></div></section>
          <section v-if="showAdvanced" class="advanced"><h3>Advanced HTML</h3><textarea v-model="advancedTemplate" @change="setAdvanced"></textarea></section>
        </div>
      </aside>
    </div>
  </div>
</template>
<script lang="ts">
import { defineComponent } from 'vue';
import { ModelNameEnum } from 'models/types';
import { PrintTemplate } from 'models/baseModels/PrintTemplate';
import type { Doc } from 'fyo/model/doc';
import type { PrintValues } from 'src/utils/types';
import { getDocFromNameIfExistsElseNew } from 'src/utils/ui';
import { getPrintTemplatePropValues } from 'src/utils/printTemplates';
import { getTemplatePreset, templatePresetNames, TemplatePresetName } from 'src/utils/templatePresets';
import PrintContainer from '../components/PrintContainer.vue';
const Row={props:['label'],template:'<label class="row"><span>{{label}}</span><slot /></label>'};
const Check={props:['label','modelValue'],emits:['update:modelValue','change'],template:'<label class="check"><input type="checkbox" :checked="modelValue" @change="$emit(\'update:modelValue\',$event.target.checked);$emit(\'change\')" /><span>{{label}}</span></label>'};
export default defineComponent({name:'TemplateDesignerWindow',components:{PrintContainer,Row,Check},props:{name:{type:String,required:true}},data(){return{doc:null as PrintTemplate|null,displayDoc:null as Doc|null,values:null as PrintValues|null,templateName:this.name,activePreset:'Professional' as TemplatePresetName,selectedId:'',selectedLabel:'',activeTab:'layout',zoom:.75,showAdvanced:false,advancedTemplate:'',history:[] as string[],historyIndex:-1,settings:{companyName:true,address:true,phone:true,email:true,title:true,number:true,subtotal:true,discount:true,tax:true,payments:true,balance:true,terms:true,pageNumbers:true,footer:'Thank you for your business.',font:'Inter',accent:'#00AFC1'},print:{paper:'Letter',orientation:'Portrait',margins:'0.5in',repeatHeader:true,fitWidth:true},controls:{align:'left',padding:'',marginTop:'',marginBottom:'',width:'',height:'',fontSize:'14px',weight:'400',fontStyle:'normal',textColor:'#14202B',fill:'#FFFFFF',border:'#DCE7EF',logoWidth:'240px',logoHeight:'80px'},columns:[{key:'item',label:'Item',visible:true},{key:'quantity',label:'Quantity',visible:true},{key:'rate',label:'Rate',visible:true},{key:'amount',label:'Amount',visible:true}],presets:templatePresetNames,blocks:[{id:'text',label:'Text'},{id:'heading',label:'Heading'},{id:'divider',label:'Divider'},{id:'spacer',label:'Spacer'},{id:'logo',label:'Company Logo'},{id:'table',label:'Items Table'}],tabs:[{id:'layout',label:'Layout'},{id:'header',label:'Header'},{id:'fields',label:'Fields'},{id:'columns',label:'Columns'},{id:'totals',label:'Totals'},{id:'footer',label:'Footer'},{id:'logo',label:'Logo'},{id:'typography',label:'Type'},{id:'colors',label:'Colors'},{id:'print',label:'Print'},{id:'position',label:'Position'}],fieldOptions:[{label:'Company Name',path:'print.companyName'},{label:'Invoice Number',path:'doc.name'},{label:'Date',path:'doc.date'},{label:'Customer',path:'doc.links.party.name'},{label:'Customer Address',path:'doc.links.party.address'},{label:'Subtotal',path:'doc.subTotal'},{label:'Grand Total',path:'doc.grandTotal'},{label:'Amount in Words',path:'doc.grandTotalInWords'},{label:'Terms',path:'print.termsAndConditions'}]};},computed:{canUndo(){return this.historyIndex>0},canRedo(){return this.historyIndex<this.history.length-1},logo(){const logo=this.values?.print?.logo;return typeof logo==='string'?logo:''},fontSizes(){return ['9px','10px','11px','12px','14px','16px','18px','20px','24px','28px','32px']}},async mounted(){await this.load();},methods:{async load(){this.doc=(await getDocFromNameIfExistsElseNew(ModelNameEnum.PrintTemplate,this.name)) as PrintTemplate;if(!this.doc.type)await this.doc.set('type',ModelNameEnum.SalesInvoice);const docType=this.doc.type||ModelNameEnum.SalesInvoice;if(!this.doc.template)await this.doc.set('template',getTemplatePreset('Professional'));if(this.doc.template){const normalized=this.ensureElementIds(this.doc.template);if(normalized!==this.doc.template)await this.doc.set('template',normalized);}this.templateName=this.doc.name||this.name;this.advancedTemplate=this.doc.template||'';const list=(await this.fyo.db.getAll(docType,{limit:1,order:'desc',orderBy:'created',filters:{cancelled:false}})) as Array<{name:string}>;if(list[0])await this.selectDisplay(list[0].name);this.pushHistory(this.doc.template||'');},async selectDisplay(name:string){this.displayDoc=await getDocFromNameIfExistsElseNew(this.doc!.type||ModelNameEnum.SalesInvoice,name);this.values=await getPrintTemplatePropValues(this.displayDoc);},async saveName(){await this.doc?.set('name',this.templateName);},async save(){if(!this.doc)return;await this.doc.sync();this.pushHistory(this.doc.template||'');},async refreshTemplate(){this.pushHistory(this.doc?.template||'');},pushHistory(value:string){if(!value)return;this.history=this.history.slice(0,this.historyIndex+1);this.history.push(value);if(this.history.length>40)this.history.shift();this.historyIndex=this.history.length-1;},async setTemplate(value:string){const normalized=this.ensureElementIds(value);await this.doc?.set('template',normalized);this.advancedTemplate=normalized;this.pushHistory(normalized);},async applyPreset(name:TemplatePresetName){if(!this.doc)return;await this.setTemplate(getTemplatePreset(name));this.activePreset=name;},source(){return new DOMParser().parseFromString(this.doc?.template||'','text/html')},ensureElementIds(template:string){const d=new DOMParser().parseFromString(template,'text/html');let changed=false;let index=0;for(const node of Array.from(d.body.querySelectorAll('*'))){if(node.tagName==='SCRIPT'||node.tagName==='STYLE')continue;if(!node.getAttribute('data-cb-id')){node.setAttribute('data-cb-id','cb-'+index++);changed=true;}}return changed?d.body.innerHTML:template},find(){if(!this.selectedId)return null;const d=this.source();return Array.from(d.body.querySelectorAll('*')).find(n=>n.getAttribute('data-cb-id')===this.selectedId) as HTMLElement|null},selectElement(id:string){this.selectedId=id;const el=this.find();this.selectedLabel=el?.tagName?.toLowerCase()||'Element';this.syncControls(el);},syncControls(el:HTMLElement|null){if(!el)return;this.controls.align=el.style.textAlign||'left';this.controls.padding=el.style.padding||'';this.controls.marginTop=el.style.marginTop||'';this.controls.marginBottom=el.style.marginBottom||'';this.controls.width=el.style.width||'';this.controls.height=el.style.height||'';this.controls.fontSize=el.style.fontSize||'14px';this.controls.weight=el.style.fontWeight||'400';this.controls.fontStyle=el.style.fontStyle||'normal';this.controls.textColor=el.style.color||'#14202B';this.controls.fill=el.style.backgroundColor||'#FFFFFF';this.controls.border=el.style.borderColor||'#DCE7EF';},async style(prop:string,value:string){const d=this.source();const el=Array.from(d.body.querySelectorAll('*')).find(n=>n.getAttribute('data-cb-id')===this.selectedId) as HTMLElement|null;if(!el)return;el.style.setProperty(prop,value);await this.setTemplate(d.body.innerHTML)},async insertField(path:string){const d=this.source();const el=d.createElement('div');el.setAttribute('data-cb-id',`cb-${Date.now()}`);el.style.margin='8px 0';el.textContent=`{{ ${path} }}`;d.body.append(el);await this.setTemplate(d.body.innerHTML);this.selectedId=el.getAttribute('data-cb-id')||'';},async insertBlock(block:{id:string;label:string}){const d=this.source();const el=d.createElement('div');const id=`cb-${Date.now().toString(36)}`;el.setAttribute('data-cb-id',id);el.style.margin='8px 0';if(block.id==='heading'){el.textContent='New Heading';el.style.fontSize='20px';el.style.fontWeight='700'}else if(block.id==='divider'){el.innerHTML='<hr style="border:0;border-top:1px solid #DCE7EF;" />'}else if(block.id==='spacer'){el.innerHTML='&nbsp;';el.style.height='24px'}else if(block.id==='logo'){el.innerHTML='<img v-if="print.logo" :src="print.logo" alt="Company Logo" style="max-height:80px;max-width:240px;object-fit:contain;" />';el.style.textAlign='center'}else if(block.id==='table'){el.innerHTML='<table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left">Item</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr v-for="item in doc.items"><td>{{ item.item }}</td><td>{{ item.quantity }}</td><td>{{ item.rate }}</td><td>{{ item.amount }}</td></tr></tbody></table>'}else{el.textContent='New text'}d.body.append(el);await this.setTemplate(d.body.innerHTML);this.selectedId=id;},async move(direction:number){const d=this.source();const el=this.find();if(!el)return;const sib=direction<0?el.previousElementSibling:el.nextElementSibling;if(!sib)return;direction<0?sib.before(el):sib.after(el);await this.setTemplate(d.body.innerHTML)},async nudge(px:number){await this.style('margin-left',`${px}px`)},async duplicate(){const d=this.source();const el=this.find();if(!el)return;const c=el.cloneNode(true) as HTMLElement;c.setAttribute('data-cb-id',`cb-${Date.now()}`);el.after(c);await this.setTemplate(d.body.innerHTML)},async deleteElement(){const d=this.source();const el=this.find();if(!el)return;el.remove();this.selectedId='';await this.setTemplate(d.body.innerHTML)},async moveColumn(i:number,direction:number){const next=i+direction;if(next<0||next>=this.columns.length)return;const item=this.columns.splice(i,1)[0];this.columns.splice(next,0,item);await this.refreshTemplate()},async updateColumn(_i:number){await this.refreshTemplate()},async setGlobalStyle(prop:string,value:string){const d=this.source();const root=d.body.firstElementChild as HTMLElement|null;if(root)root.style.setProperty(prop,value);await this.setTemplate(d.body.innerHTML)},async setAdvanced(){await this.setTemplate(this.advancedTemplate)},undo(){if(!this.canUndo)return;this.historyIndex--;this.doc!.set('template',this.history[this.historyIndex]);this.advancedTemplate=this.history[this.historyIndex]},redo(){if(!this.canRedo)return;this.historyIndex++;this.doc!.set('template',this.history[this.historyIndex]);this.advancedTemplate=this.history[this.historyIndex]},fit(){this.zoom=.75},dropElement(e:DragEvent){e.preventDefault()},previewPrint(){const container=this.$refs.printContainer as {savePDF?: (name?:string,shouldPrint?:boolean)=>Promise<unknown>}|undefined;void container?.savePDF?.(this.doc?.name,true)}}});
</script>
<style scoped>
.designer-window{height:100vh;display:flex;flex-direction:column;background:#F5F9FC;color:#14202B;font-family:Inter,system-ui,sans-serif}.designer-header{height:58px;display:flex;align-items:center;gap:20px;padding:0 16px;background:#07345C;color:#fff;box-sizing:border-box;flex-shrink:0}.brand{display:flex;flex-direction:column;min-width:175px}.brand strong{font-size:16px}.brand span{font-size:9px;color:#9FDCE6}.template-title{display:flex;align-items:center;gap:8px;flex:1}.template-title span:first-child{font-size:10px;text-transform:uppercase;opacity:.7}.template-title input{height:32px;width:240px;border:1px solid #2D5877;background:#062B4A;color:#fff;border-radius:5px;padding:0 9px;font-weight:700}.dirty{color:#FFD166!important;font-size:10px!important}.header-actions{display:flex;gap:6px}.header-actions button,.canvas-controls button,.inspector-header button{height:30px;border:1px solid #AFC6D5;background:#fff;color:#173B59;border-radius:5px;padding:0 9px;font-size:10px}.header-actions button{background:#0B4163;border-color:#376785;color:#fff}.header-actions .primary{background:#00AFC1;border-color:#00AFC1}.workspace{display:grid;grid-template-columns:190px minmax(420px,1fr) 360px;min-height:0;flex:1}.left-rail{background:#062B4A;color:#D7ECF6;padding:12px 9px;overflow:auto}.rail-title{font-size:9px;text-transform:uppercase;letter-spacing:1px;color:#77A8BE;font-weight:800;padding:8px 8px 5px}.left-rail button{width:100%;display:flex;align-items:center;gap:8px;border:0;background:transparent;color:#D7ECF6;text-align:left;border-radius:5px;padding:8px;font-size:10px;cursor:pointer}.left-rail button:hover,.left-rail button.active{background:#0A4268;color:#fff}.swatch{width:18px;height:24px;background:#fff;border-radius:2px;box-shadow:inset 0 3px #07345C}.swatch.simple{box-shadow:none}.swatch.modern{box-shadow:inset 0 3px #18C6D3}.swatch.classic{box-shadow:inset 0 3px #586874}.swatch.custom{border:1px dashed #18C6D3;box-sizing:border-box}.plus{width:18px;text-align:center;color:#18C6D3;font-size:14px}.rail-divider{height:1px;background:#1A506C;margin:9px 7px}.canvas-area{display:flex;flex-direction:column;min-width:0;background:#E8EEF3}.canvas-toolbar{height:48px;display:flex;justify-content:space-between;align-items:center;padding:0 14px;background:#F8FBFD;border-bottom:1px solid #D3DFE7}.canvas-toolbar strong{font-size:12px;color:#07345C}.canvas-toolbar span{display:block;font-size:9px;color:#7892A3}.canvas-controls{display:flex;gap:4px;align-items:center}.canvas-controls span{display:inline;color:#45687F;padding:0 5px}.paper-stage{flex:1;overflow:auto;display:flex;justify-content:center;align-items:flex-start;padding:26px}.paper-shell{transform-origin:top center;box-shadow:0 5px 22px rgba(7,52,92,.16)}.inspector-panel{display:flex;flex-direction:column;min-width:0;background:#fff;border-left:1px solid #C9D6DF}.inspector-header{height:58px;display:flex;justify-content:space-between;align-items:center;padding:0 12px;border-bottom:1px solid #DCE7EF}.inspector-header span{display:block;font-size:9px;color:#6D8798;text-transform:uppercase}.inspector-header strong{display:block;color:#07345C;font-size:13px;margin-top:3px}.tabs{display:flex;flex-wrap:wrap;border-bottom:1px solid #DCE7EF;padding:5px}.tabs button{border:0;background:transparent;color:#6A8292;padding:6px 7px;font-size:9px;border-radius:4px}.tabs button.active{background:#E8FAFC;color:#008E9F;font-weight:800}.inspector-body{overflow:auto;padding:12px}.inspector-body h3{font-size:12px;color:#07345C;margin:0 0 10px}.row{display:grid;grid-template-columns:90px 1fr;align-items:center;gap:8px;margin-bottom:8px;font-size:10px;color:#5C7688}.row input,.row select,.row textarea,.inspector-body textarea{width:100%;box-sizing:border-box;height:29px;border:1px solid #D1DDE5;border-radius:5px;padding:0 7px;background:#fff;color:#173B59;font-size:10px}.row textarea{height:70px;padding-top:7px}.check{display:flex;gap:7px;align-items:center;padding:7px 0;font-size:10px;color:#45667